    for n in (2, 3, 4, 6, 8, 12, 20, 40, 80):
        for p in (0.5, 0.5, 0.2, 0.85):
            tests.append(fmt([1 if rng.random() < p else 0 for _ in range(n)]))
    N = 5 * 10 ** 5
    tests.append(fmt([rng.randint(0, 1) for _ in range(N)]))
    tests.append(fmt([i % 2 for i in range(N)]))
    tests.append(fmt([0] * (N // 2) + [1] * (N // 2)))
    tests.append(fmt([1 if rng.random() < 0.6 else 0 for _ in range(N)]))
    return tests

